from collections import deque
from copy import deepcopy


class QuotaEngine:
    def __init__(self, policies: list[dict], allow_users: list[str] = ()):
        self._policies = deepcopy(policies)
        self._allow_users = set(allow_users)
        # Each policy owns an independent mapping of bucket keys to states.
        self._buckets = [{} for _ in self._policies]

    def request(self, t_ms: int, attrs: dict, cost: int = 1) -> dict:
        if attrs["user"] in self._allow_users:
            return {
                "allowed": True,
                "retry_after_ms": 0,
                "limited_by": None,
                "remaining": {},
            }

        applicable = []
        allowed = True
        worst_retry = 0
        limited_by = None
        token_cost = cost * 1000

        # First refresh and evaluate every applicable bucket. Charging is
        # deferred until the overall decision and retries are known.
        for policy, buckets in zip(self._policies, self._buckets):
            routes = policy.get("routes")
            if routes is not None and not any(
                attrs["route"].startswith(prefix) for prefix in routes
            ):
                continue

            per = policy["per"]
            key = None if per == "global" else attrs[per]
            limit = policy.get("overrides", {}).get(key, policy["limit"])
            kind = policy["kind"]
            state = buckets.get(key)
            retry = 0

            if kind == "token":
                capacity = limit * 1000
                if state is None:
                    state = {"held": capacity, "updated": t_ms}
                    buckets[key] = state

                state["held"] = min(
                    capacity,
                    state["held"]
                    + (t_ms - state["updated"]) * policy["rate"],
                )
                state["updated"] = t_ms
                accepts = state["held"] >= token_cost

                if not accepts:
                    if cost > limit:
                        retry = None
                    else:
                        deficit = token_cost - state["held"]
                        rate = policy["rate"]
                        retry = (deficit + rate - 1) // rate

            elif kind == "fixed":
                window_ms = policy["window_ms"]
                index = t_ms // window_ms

                if state is None:
                    state = {"index": index, "used": 0}
                    buckets[key] = state
                elif index > state["index"]:
                    state["index"] = index
                    state["used"] = 0

                accepts = state["used"] + cost <= limit
                if not accepts:
                    retry = (
                        None
                        if cost > limit
                        else (index + 1) * window_ms - t_ms
                    )

            else:  # sliding
                window_ms = policy["window_ms"]
                if state is None:
                    state = {"entries": deque(), "used": 0}
                    buckets[key] = state

                entries = state["entries"]
                cutoff = t_ms - window_ms
                while entries and entries[0][0] <= cutoff:
                    _, expired_cost = entries.popleft()
                    state["used"] -= expired_cost

                accepts = state["used"] + cost <= limit
                if not accepts:
                    if cost > limit:
                        retry = None
                    else:
                        # Simulate expiration without modifying the log.
                        future_used = state["used"]
                        target = limit - cost
                        for entry_time, entry_cost in entries:
                            future_used -= entry_cost
                            if future_used <= target:
                                retry = entry_time + window_ms - t_ms
                                break

            applicable.append((policy, state, limit))

            if not accepts:
                allowed = False
                # None is greater than any finite retry. Strict comparison
                # preserves constructor order when retries tie.
                if limited_by is None or (
                    worst_retry is not None
                    and (retry is None or retry > worst_retry)
                ):
                    limited_by = policy["name"]
                    worst_retry = retry

        # Apply charges only after all policies have been evaluated.
        remaining = {}
        for policy, state, limit in applicable:
            kind = policy["kind"]
            should_charge = allowed or policy.get("charge_denied", False)

            if kind == "token":
                if should_charge:
                    state["held"] -= min(token_cost, state["held"])
                remaining[policy["name"]] = state["held"] // 1000

            elif kind == "fixed":
                if should_charge:
                    state["used"] += cost
                remaining[policy["name"]] = max(0, limit - state["used"])

            else:  # sliding
                if should_charge:
                    state["entries"].append((t_ms, cost))
                    state["used"] += cost
                remaining[policy["name"]] = max(0, limit - state["used"])

        return {
            "allowed": allowed,
            "retry_after_ms": 0 if allowed else worst_retry,
            "limited_by": None if allowed else limited_by,
            "remaining": remaining,
        }
